package fr.niakimbo.verso.generateur

import fr.niakimbo.verso.matrix.MatrixFrame
import fr.niakimbo.verso.modele.Modele
import fr.niakimbo.verso.reglage.EntreeCatalogue
import fr.niakimbo.verso.reglage.Personnalisation
import fr.niakimbo.verso.reglage.Reglage
import fr.niakimbo.verso.reglage.VersionModele
import kotlin.math.roundToInt
import kotlin.math.roundToLong

/**
 * « NC MODS V2 » : animation de démarrage (NC qui brille, clignote, s'efface, anneau qui tourne,
 * « MODS » qui défile). Images relevées LED par LED sur la vidéo de Nico (6,5 s), grille recalée : cadran complet et uniforme.
 *
 * Réglages : fondu d'entrée et pause (matrice éteinte) avant de rejouer l'animation.
 */
object NcModsV2 {
    private val FONDU = Reglage.Curseur(
        cle = "v1.fondu", titre = "Fondu d'entrée",
        description = "Le NC s'allume doucement au début de chaque passage. 0 = d'un coup.",
        min = 0f, max = 2f, defaut = 0.6f, crans = 19,
        format = { if (it < 0.05f) "Aucun" else "%.1f s".format(it) },
    )
    private val PAUSE = Reglage.Curseur(
        cle = "v1.pause", titre = "Pause avant de rejouer",
        description = "Temps matrice éteinte entre deux passages. 0 = enchaîne direct.",
        min = 0f, max = 30f, defaut = 3f, crans = 29,
        format = { if (it < 0.5f) "Aucune" else "${it.roundToInt()} s" },
    )

    /** Pas du fondu : assez fin pour être doux, au-dessus du minimum de la matrice. */
    private const val PAS_FONDU_MS = 50L

    /** « durée:169 pixels en hexa sur 2 chiffres (00-ff) », ligne par ligne. 256 niveaux : le cadran, très faible, reste uniforme. */
    private val IMAGES = listOf(
        "83:",
        "50:",
        "100:",
        "67:",
        "50:",
        "50:",
        "50:",
        "50:",
        "67:",
        "83:",
        "67:",
        "67:",
        "100:",
        "67:",
        "67:",
        "183:",
        "100:",
        "50:",
        "83:",
        "83:",
        "67:",
        "50:",
        "83:",
        "67:",
        "67:",
        "67:",
        "83:",
        "67:",
        "67:",
        "133:",
        "250:",
        "117:",
        "233:",
        "100:",
        "267:",
        "50:",
        "67:",
        "50:",
        "83:",
        "50:",
        "67:",
        "67:",
        "83:",
        "50:",
        "83:",
        "83:",
        "67:",
        "67:",
        "67:",
        "83:",
        "67:",
        "83:",
        "67:",
        "50:",
        "67:",
        "50:",
        "67:",
        "50:",
        "50:",
        "67:",
        "50:",
        "50:",
        "67:",
        "50:",
        "50:",
        "67:",
        "50:",
        "67:",
        "100:",
        "67:",
        "50:",
        "50:",
        "67:",
        "50:",
        "50:",
        "50:",
        "50:",
        "83:",
